import{_ as t}from"./plugin-vue_export-helper-c27b6911.js";import{o as e,c as a,e as n}from"./app-89d18e81.js";const s={},l=n(`<h1 id="jni-java-native-interface-基础" tabindex="-1"><a class="header-anchor" href="#jni-java-native-interface-基础" aria-hidden="true">#</a> JNI (Java Native Interface) 基础</h1><p>JNI 是一种编程框架，允许 Java 代码与使用 C、C++ 或汇编编写的本地应用和库进行交互。在逆向分析中，核心逻辑（如加密算法、核心协议）往往隐藏在 JNI 层。</p><h2 id="_1-核心概念" tabindex="-1"><a class="header-anchor" href="#_1-核心概念" aria-hidden="true">#</a> 1. 核心概念</h2><ul><li><strong>本地方法 (Native Method)</strong>: 在 Java 中声明但没有实现的方法，使用 <code>native</code> 关键字标记。</li><li><strong>动态链接库</strong>: Android 中通常是 <code>.so</code> 文件。</li><li><strong>JNIEnv</strong>: 指向 JNI 环境的指针，通过它 C/C++ 可以调用 Java 的方法、操作 Java 字段、创建 Java 对象等。</li></ul><h2 id="_2-jni-注册方式" tabindex="-1"><a class="header-anchor" href="#_2-jni-注册方式" aria-hidden="true">#</a> 2. JNI 注册方式</h2><h3 id="静态注册-static-registration" tabindex="-1"><a class="header-anchor" href="#静态注册-static-registration" aria-hidden="true">#</a> 静态注册 (Static Registration)</h3><p>根据特定的命名规则匹配：<code>Java_包名_类名_方法名</code>。</p><ul><li><strong>优点</strong>: 简单，反编译器（如 IDA）能直接搜到函数名。</li><li><strong>缺点</strong>: 灵活性差，名字长。</li><li><strong>例子</strong>:<div class="language-c line-numbers-mode" data-ext="c"><pre class="language-c"><code>JNIEXPORT jstring JNICALL
<span class="token function">Java_com_example_test_MainActivity_stringFromJNI</span><span class="token punctuation">(</span>JNIEnv<span class="token operator">*</span> env<span class="token punctuation">,</span> jobject thiz<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">(</span><span class="token operator">*</span>env<span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">NewStringUTF</span><span class="token punctuation">(</span>env<span class="token punctuation">,</span> <span class="token string">&quot;Hello from C++&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li></ul><h3 id="动态注册-dynamic-registration" tabindex="-1"><a class="header-anchor" href="#动态注册-dynamic-registration" aria-hidden="true">#</a> 动态注册 (Dynamic Registration)</h3><p>在 <code>JNI_OnLoad</code> 函数中手动建立 Java 方法与 C 函数的映射。</p><ul><li><strong>优点</strong>: 效率高，更隐蔽（IDA 中函数名不直观）。</li><li><strong>流程</strong>: <ol><li>系统加载 <code>.so</code> 时自动调用 <code>JNI_OnLoad</code>。</li><li>使用 <code>RegisterNatives</code> 函数注册。</li></ol></li><li><strong>逆向技巧</strong>: 在 IDA 中通过搜索 <code>JNI_OnLoad</code> 并定位 <code>RegisterNatives</code> 调用来找对应的 Native 实现。</li></ul><h2 id="_3-数据类型映射" tabindex="-1"><a class="header-anchor" href="#_3-数据类型映射" aria-hidden="true">#</a> 3. 数据类型映射</h2><table><thead><tr><th style="text-align:left;">Java 类型</th><th style="text-align:left;">JNI 类型</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;">boolean</td><td style="text-align:left;">jboolean</td><td style="text-align:left;">无符号 8 位</td></tr><tr><td style="text-align:left;">int</td><td style="text-align:left;">jint</td><td style="text-align:left;">有符号 32 位</td></tr><tr><td style="text-align:left;">long</td><td style="text-align:left;">jlong</td><td style="text-align:left;">有符号 64 位</td></tr><tr><td style="text-align:left;">String</td><td style="text-align:left;">jstring</td><td style="text-align:left;">字符串对象</td></tr><tr><td style="text-align:left;">byte[]</td><td style="text-align:left;">jbyteArray</td><td style="text-align:left;">字节数组</td></tr><tr><td style="text-align:left;">Object</td><td style="text-align:left;">jobject</td><td style="text-align:left;">任意 Java 对象</td></tr><tr><td style="text-align:left;">Class</td><td style="text-align:left;">jclass</td><td style="text-align:left;">类引用</td></tr></tbody></table><h2 id="_4-逆向常用-api" tabindex="-1"><a class="header-anchor" href="#_4-逆向常用-api" aria-hidden="true">#</a> 4. 逆向常用 API</h2><ul><li><code>FindClass</code>: 获取 Java 类。</li><li><code>GetMethodID</code> / <code>GetStaticMethodID</code>: 获取方法 ID。</li><li><code>Call&lt;Type&gt;Method</code>: 调用方法（如 <code>CallObjectMethod</code>）。</li><li><code>GetFieldID</code> / <code>SetFieldID</code>: 操作成员变量。</li><li><code>GetStringUTFChars</code>: 将 Java 字符串转为 C 字符串。</li></ul><h2 id="_5-安全与防御" tabindex="-1"><a class="header-anchor" href="#_5-安全与防御" aria-hidden="true">#</a> 5. 安全与防御</h2><ul><li><strong>反调试</strong>: 在 <code>JNI_OnLoad</code> 中检查 <code>ptrace</code> 或轮询 <code>/proc/self/status</code>。</li><li><strong>代码混淆</strong>: 使用 LLVM 指令混淆（OLLVM）处理 C 代码。</li><li><strong>字符串加密</strong>: 避免敏感字符串（如秘钥）以明文形式出现在 <code>.so</code> 中。</li></ul>`,17),i=[l];function o(d,r){return e(),a("div",null,i)}const h=t(s,[["render",o],["__file","JNI.html.vue"]]);export{h as default};
